'use client';

import { useState, useEffect } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import { productsApi } from '@/lib/api/products';
import Image from 'next/image';
import Link from 'next/link';

export default function ProductsPage() {
  const t = useTranslations('products');
  const locale = useLocale();

  const [products, setProducts] = useState<any[]>([]);
  const [categories, setCategories] = useState<string[]>([]);
  const [masters, setMasters] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [filters, setFilters] = useState({
    category: '',
    master: '',
    minPrice: '',
    maxPrice: '',
    sortBy: 'created_at',
  });

  const [pagination, setPagination] = useState<{
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  }>({
    page: 1,
    limit: 24,
    total: 0,
    totalPages: 0,
  });

  useEffect(() => {
    fetchData();
  }, [filters, pagination.page]);

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [productsData, categoriesData, mastersData] = await Promise.all([
        productsApi.getProducts({
          ...filters,
          page: pagination.page,
          limit: pagination.limit,
        }),
        productsApi.getCategories(),
        productsApi.getMasters(),
      ]);

      setProducts(productsData.products || []);
      setCategories(categoriesData.categories || []);
      setMasters(mastersData.masters || []);
      setPagination(productsData.pagination || pagination);
    } catch (err) {
      setError('Failed to fetch products');
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (key: string, value: string) => {
    setFilters({ ...filters, [key]: value });
    setPagination({ ...pagination, page: 1 });
  };

  const getProductUrl = (productId: string) => {
    const name = products.find(p => p.id === productId)?.name || 'product';
    const slug = name.toLowerCase().replace(/\s+/g, '-');
    return `/${locale}/products/${productId}/${slug}`;
  };

  const getProductName = (product: any) => {
    if (locale === 'zh-CN' || locale === 'zh-TW') {
      return locale === 'zh-TW' ? (product.nameZhTw || product.name) : product.name;
    }
    return product.nameEn || product.name;
  };

  const getProductDescription = (product: any) => {
    if (locale === 'zh-CN' || locale === 'zh-TW') {
      return locale === 'zh-TW' ? (product.descriptionZhTw || product.description) : product.description;
    }
    return product.descriptionEn || product.description;
  };

  if (loading && products.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-red-600">{error}</div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-6">{t('title')}</h1>

        <div className="bg-white p-6 rounded-lg shadow-md mb-8">
          <div className="grid md:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">{t('filter.all')}</label>
              <select
                value={filters.category}
                onChange={(e) => handleFilterChange('category', e.target.value)}
                className="w-full border border-gray-300 rounded px-3 py-2"
              >
                <option value="">{t('filter.all')}</option>
                {categories.map((category) => (
                  <option key={category} value={category}>
                    {t(`filter.${category}`)}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">{t('filterByMaster')}</label>
              <select
                value={filters.master}
                onChange={(e) => handleFilterChange('master', e.target.value)}
                className="w-full border border-gray-300 rounded px-3 py-2"
              >
                <option value="">{t('allMasters')}</option>
                {masters.map((master) => (
                  <option key={master} value={master}>
                    {master}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">{t('priceRange')}</label>
              <div className="flex gap-2">
                <input
                  type="number"
                  placeholder={t('from')}
                  value={filters.minPrice}
                  onChange={(e) => handleFilterChange('minPrice', e.target.value)}
                  className="w-1/2 border border-gray-300 rounded px-3 py-2"
                />
                <input
                  type="number"
                  placeholder={t('to')}
                  value={filters.maxPrice}
                  onChange={(e) => handleFilterChange('maxPrice', e.target.value)}
                  className="w-1/2 border border-gray-300 rounded px-3 py-2"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">{t('sortBy')}</label>
              <select
                value={filters.sortBy}
                onChange={(e) => handleFilterChange('sortBy', e.target.value)}
                className="w-full border border-gray-300 rounded px-3 py-2"
              >
                <option value="created_at">{t('sortBy')}</option>
                <option value="price_asc">{t('priceAsc')}</option>
                <option value="price_desc">{t('priceDesc')}</option>
              </select>
            </div>
          </div>

          <div className="mt-4 flex gap-2">
            <button
              onClick={() => setFilters({
                category: '',
                master: '',
                minPrice: '',
                maxPrice: '',
                sortBy: 'created_at',
              })}
              className="px-4 py-2 border border-gray-300 rounded hover:bg-gray-50"
            >
              {t('clear')}
            </button>
          </div>
        </div>
      </div>

      {products.length === 0 ? (
        <div className="text-center py-12">
          <p className="text-gray-600">No products found</p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6">
            {products.map((product) => (
              <Link
                key={product.id}
                href={getProductUrl(product.id)}
                className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow"
              >
                {product.images && product.images.length > 0 && (
                  <div className="aspect-square relative">
                    <Image
                      src={product.images[0]}
                      alt={getProductName(product)}
                      fill
                      className="object-cover"
                      sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 25vw"
                    />
                  </div>
                )}
                <div className="p-4">
                  <h3 className="font-semibold text-lg mb-2 line-clamp-2">
                    {getProductName(product)}
                  </h3>
                  <p className="text-gray-600 text-sm mb-3 line-clamp-2">
                    {getProductDescription(product)}
                  </p>
                  <div className="flex items-center justify-between">
                    <span className="text-xl font-bold text-blue-600">
                      ¥{product.price.toFixed(2)}
                    </span>
                    <span className="text-sm text-gray-500">
                      {t(`filter.${product.category}`)}
                    </span>
                  </div>
                </div>
              </Link>
            ))}
          </div>

          {pagination.totalPages > 1 && (
            <div className="mt-8 flex justify-center gap-2">
              <button
                onClick={() => setPagination({ ...pagination, page: pagination.page - 1 })}
                disabled={pagination.page === 1}
                className="px-4 py-2 bg-white border border-gray-300 rounded hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Previous
              </button>
              <span className="px-4 py-2 bg-blue-600 text-white rounded">
                {pagination.page} / {pagination.totalPages}
              </span>
              <button
                onClick={() => setPagination({ ...pagination, page: pagination.page + 1 })}
                disabled={pagination.page === pagination.totalPages}
                className="px-4 py-2 bg-white border border-gray-300 rounded hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Next
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
